  [("ventaja", "diferencia entre atacantes y defensores en un sector"), ("desmarcarse", "moverse sin balón para quedar libre de los defensores"), ("cambio de lado", "pase largo hacia el otro lado de la cancha"), ("sector con ventaja", "sector donde hay más atacantes que defensores"), ("desventaja", "tener menos atacantes que defensores en un sector")],
